// Pokémon Champions for the battle engine: copies the champions and championsregma mods of Pokémon Showdown (MIT, npm
// pokemon-showdown 0.11.11: dist/data/mods/*) into engine/src/champions/ as ES modules, and the formats that use them into
// engine/src/champions/formats.mjs. engine/src/champions.mjs registers them on @pkmn/sim's Dex (which does not ship them).
//   npm pack pokemon-showdown@0.11.11 && tar xzf pokemon-showdown-0.11.11.tgz && node scripts/build_champions.mjs package
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const pkg = process.argv[2];
if (!pkg) { console.error("usage: node scripts/build_champions.mjs <pokemon-showdown package dir>"); process.exit(1); }
const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const out = join(root, "engine", "src", "champions");
mkdirSync(out, { recursive: true });
const MODS = ["champions", "championsregma"];
const FILES = { scripts: "Scripts", abilities: "Abilities", conditions: "Conditions", "formats-data": "FormatsData", items: "Items",
  learnsets: "Learnsets", moves: "Moves", rulesets: "Rulesets", pokedex: "Pokedex" };
const version = JSON.parse(readFileSync(join(pkg, "package.json"), "utf8")).version;
const header = (mod, file) => `// Generated by scripts/build_champions.mjs from Pokémon Showdown ${version} (MIT), data/mods/${mod}/${file}.js. Do not edit.\n`;

const index = [];
for (const mod of MODS) {
  for (const [file, key] of Object.entries(FILES)) {
    const src = join(pkg, "dist", "data", "mods", mod, `${file}.js`);
    if (!existsSync(src)) continue;
    let code = readFileSync(src, "utf8");
    // the build is esbuild's CommonJS: keep the object literal, export it as an ES module
    const at = code.indexOf(`const ${key} = `);
    if (at < 0) throw new Error(`${mod}/${file}: no 'const ${key} ='`);
    code = code.slice(at).replace(`const ${key} = `, `export const ${key} = `).replace(/\n\/\/# sourceMappingURL=.*$/m, "");
    if (/\brequire\(/.test(code)) throw new Error(`${mod}/${file} needs other modules`);
    const name = `${mod}-${file}.mjs`;
    writeFileSync(join(out, name), header(mod, file) + code);
    index.push({ mod, key, name });
  }
}
// the formats of these mods (not the random battle: its team generator is not in the mods)
const require = createRequire(import.meta.url);
const { Formats } = require(join(pkg, "dist", "config", "formats.js"));
const formats = Formats.filter((f) => MODS.includes(f.mod) && f.team !== "random").map((f) => {
  const g = { section: "Champions", ...f };
  if (g.battle?.trunc) g.battle = { trunc: "Math.trunc" };
  return g;
});
let ftext = JSON.stringify(formats, null, 1).replace(/"Math\.trunc"/g, "Math.trunc");
writeFileSync(join(out, "formats.mjs"), `// Generated by scripts/build_champions.mjs from Pokémon Showdown ${version} (MIT), config/formats.js. Do not edit.\nexport const Formats = ${ftext};\n`);
// the registry's imports
const lines = index.map((x, i) => `import { ${x.key} as m${i} } from "./${x.name}";`);
const data = MODS.map((mod) => `  ${mod}: { ${index.map((x, i) => (x.mod === mod ? `${x.key}: m${i}` : "")).filter(Boolean).join(", ")} },`);
writeFileSync(join(out, "index.mjs"), `// Generated by scripts/build_champions.mjs. Do not edit.\n${lines.join("\n")}\nexport { Formats } from "./formats.mjs";\nexport const MODS = {\n${data.join("\n")}\n};\nexport const SOURCE = "Pokémon Showdown ${version}";\n`);
console.log(`${index.length} files, ${formats.length} formats from Pokémon Showdown ${version}`);
